pt-BR.code:
from collections import deque

vizinhos = {"A": ["C", "D"], "B": ["C"], "C": ["E"], "D": ["E"], "E": []}
grau = {"A": 0, "B": 0, "C": 2, "D": 1, "E": 2}
fila = deque(["A", "B"])
ordem = ""
while fila:
    v = fila.popleft()
    ordem += v
    for w in vizinhos[v]:
        grau[w] -= 1
        if grau[w] == 0:
            fila.append(w)
print(ordem)

